import html, json
from pathlib import Path

def _events(bundle):
    return [json.loads(x) for x in (bundle/'trajectory/events.jsonl').read_text(encoding='utf-8').splitlines() if x.strip()]

def render_timeline(bundle: Path):
    events=_events(bundle); rows=[]
    for e in events:
        d=e.get('data') or {}; text=d.get('text') or d.get('content') or d.get('message') or d.get('command') or json.dumps(d,ensure_ascii=False)
        rows.append(f"<article data-type='{html.escape(e['event_type'])}' data-search='{html.escape(str(text).lower())}'><small>#{e['source_line']} · {html.escape(e.get('timestamp') or '')} · {html.escape(e['event_type'])} · {html.escape(e['event_id'])}</small><pre>{html.escape(str(text))}</pre></article>")
    doc="""<!doctype html><meta charset='utf-8'><title>AgentTraceKit timeline</title><style>body{font:15px system-ui;max-width:1100px;margin:2rem auto;padding:0 1rem;background:#f7f7f8;color:#222}header{position:sticky;top:0;background:#f7f7f8;padding:1rem 0;z-index:2}input{width:100%;padding:.7rem;border:1px solid #bbb;border-radius:6px}select,button{margin:.4rem .3rem .4rem 0;padding:.45rem}article{background:white;border:1px solid #ddd;border-radius:8px;padding:.7rem;margin:.6rem 0}small{color:#666}pre{white-space:pre-wrap;word-break:break-word;margin:.5rem 0 0}article[data-type=tool_call]{border-left:4px solid #e59f00}article[data-type=tool_result]{border-left:4px solid #4c9}article[data-type=user_message]{border-left:4px solid #58f}article[data-type=assistant_message]{border-left:4px solid #888}</style><header><h1>AgentTraceKit timeline</h1><input id='q' placeholder='Search this session…'><select id='kind'><option value=''>All event types</option><option>user_message</option><option>assistant_message</option><option>tool_call</option><option>tool_result</option><option>lifecycle</option><option>unknown</option></select><button id='prev'>Previous match</button><button id='next'>Next match</button><button id='toggle'>Collapse/expand</button></header><main>"""+''.join(rows)+"</main><script>const arts=[...document.querySelectorAll('article')];function filter(){let q=document.querySelector('#q').value.toLowerCase(),k=document.querySelector('#kind').value;arts.forEach(a=>a.hidden=(q&&!a.dataset.search.includes(q))||(k&&a.dataset.type!==k))}q.oninput=filter;kind.onchange=filter;toggle.onclick=()=>arts.forEach(a=>a.querySelector('pre').hidden=!a.querySelector('pre').hidden);let pos=-1;function move(d){let vis=arts.filter(a=>!a.hidden);if(!vis.length)return;pos=(pos+d+vis.length)%vis.length;vis[pos].scrollIntoView({behavior:'smooth',block:'center'});vis[pos].style.outline='3px solid #58f';setTimeout(()=>vis[pos].style.outline='',700)}prev.onclick=()=>move(-1);next.onclick=()=>move(1)</script>"""
    (bundle/'timeline.html').write_text(doc,encoding='utf-8'); return bundle/'timeline.html'

def render_annotation_workbench(bundle: Path):
    interactions=[json.loads(x) for x in (bundle/'trajectory/interactions.jsonl').read_text(encoding='utf-8').splitlines() if x.strip()]
    ontology=json.loads((bundle/'annotation/ontology.json').read_text(encoding='utf-8'))
    existing=(bundle/'annotation/annotations.jsonl').read_text(encoding='utf-8') if (bundle/'annotation/annotations.jsonl').exists() else ''
    payload=json.dumps({'interactions':interactions,'labels':ontology.get('labels',[]),'existing':existing},ensure_ascii=False).replace('</','<\\/')
    doc="""<!doctype html><meta charset='utf-8'><title>AgentTraceKit annotation workbench</title><style>body{font:15px system-ui;max-width:1200px;margin:1rem auto;padding:0 1rem;color:#222}header{position:sticky;top:0;background:white;padding:.5rem 0;border-bottom:1px solid #ddd;z-index:2}main{display:grid;grid-template-columns:280px 1fr;gap:1rem}nav button{display:block;width:100%;text-align:left;margin:.25rem 0;padding:.6rem;border:1px solid #ddd;background:#fafafa;border-radius:5px}.card{border:1px solid #ddd;border-radius:8px;padding:1rem;margin:.6rem 0}.msg{white-space:pre-wrap;background:#f7f7f8;padding:.7rem;border-radius:5px;max-height:260px;overflow:auto}textarea{width:100%;min-height:100px}select,input,button{padding:.5rem;margin:.25rem 0}.muted{color:#666}</style><header><b>AgentTraceKit annotation workbench</b> <span id='count'></span><button id='download'>Download annotations.jsonl</button><button id='save'>Save browser draft</button></header><main><nav id='nav'></nav><section id='detail'></section></main><script>const DATA="""+payload+""";let anns=[];try{anns=DATA.existing.split(/\\n/).filter(Boolean).map(JSON.parse)}catch(e){};let current=0;const nav=document.querySelector('#nav'),detail=document.querySelector('#detail');function renderNav(){nav.innerHTML=DATA.interactions.map((i,n)=>`<button onclick='selectI(${n})'>${n+1}. ${esc(i.user_message).slice(0,45)||'(empty)'}</button>`).join('');count.textContent=`${anns.length} saved annotations`};function esc(s){return String(s||'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))};function selectI(n){current=n;let i=DATA.interactions[n];let old=anns.find(a=>a.interaction_id===i.interaction_id)||{};detail.innerHTML=`<div class='card'><h2>${n+1}. ${esc(i.interaction_id)}</h2><b>User message</b><div class='msg'>${esc(i.user_message)}</div><p class='muted'>Events: ${(i.event_ids||[]).join(', ')}<br>Tool calls: ${(i.tool_calls||[]).length}</p><label>Label <select id='label'>${DATA.labels.map(l=>`<option value='${esc(l.name)}' ${old.label===l.name?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label><br><label>Status <select id='status'><option>pending</option><option>accepted</option><option>rejected</option><option>needs_adjudication</option></select></label><br><textarea id='notes' placeholder='Reviewer notes'>${esc(old.notes||'')}</textarea><br><button onclick='saveAnn()'>Save annotation</button></div>`};function saveAnn(){let i=DATA.interactions[current],a={annotation_id:'ann_'+crypto.randomUUID().replaceAll('-','').slice(0,12),bundle_id:location.pathname,interaction_id:i.interaction_id,event_ids:i.event_ids||[],label:label.value,review_status:status.value,reviewer:'',severity:'',attribution:'',notes:notes.value,ontology_version:'0.1',created_at:new Date().toISOString()};anns=anns.filter(x=>x.interaction_id!==i.interaction_id);anns.push(a);renderNav();selectI(current)}download.onclick=()=>{let blob=new Blob([anns.map(JSON.stringify).join('\\n')+'\\n'],{type:'application/jsonl'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='annotations.jsonl';a.click()};save.onclick=()=>localStorage.setItem('agenttracekit:'+location.pathname,JSON.stringify(anns));renderNav();selectI(0)</script>"""
    p=bundle/'annotation/workbench.html'; p.write_text(doc,encoding='utf-8'); return p
